    GroupByQuery query = GroupByQuery
        .builder()
        .setDataSource("ds")
        .setQuerySegmentSpec(Druids.newDefaultIntervalSpec("2015-09-12/2015-09-13"))
        .setDimensions(Arrays.asList(new DefaultDimensionSpec("test", "test", ColumnType.STRING)))
        .setAggregatorSpecs(Arrays.asList(new CountAggregatorFactory("count")))
        .setPostAggregatorSpecs(
            Arrays.asList(
                new ConstantPostAggregator("post", 10),
                new ConstantPostAggregator("post2", 20)
            )
        )
        .setGranularity(Granularities.DAY)
        .build();

    GroupByQueryQueryToolChest toolChest = new GroupByQueryQueryToolChest(null);
    CacheStrategy<ResultRow, Object, GroupByQuery> strategy = toolChest.getCacheStrategy(query);

    ResultRow result2 = ResultRow.of(123L, "val1", 1, 10, 20);

    Object prepared = strategy.prepareForCache(true).apply(result2);
    System.out.println("PREPARED: " + prepared);

    ObjectMapper mapper = TestHelper.makeJsonMapper();
    try {
      Object fromCache = mapper.readValue(mapper.writeValueAsBytes(prepared), strategy.getCacheObjectClazz());
      System.out.println("FROMCACHE RAW: " + fromCache);
      ResultRow restored = strategy.pullFromCache(true).apply(fromCache);
      System.out.println("RESTORED: " + restored);
      Assert.assertEquals(result2, restored);
    }
    catch (Exception e) {
      throw new RuntimeException(e);
    }
  }
}

